$('#registerForm').addEventListener('submit', async event => { event.preventDefault(); $('#registerError').textContent = ''; try { const name = $('#registerName').value.trim(); const result = await api('/api/register', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ user: name, name, pin: $('#registerPin').value, code: $('#registerCode').value.trim() }) }); currentUser = result.user; rememberUser(currentUser); await showApp(); } catch (error) { $('#registerError').textContent = error.message + (error.retry ? `（${error.retry} 秒）` : ''); } });
