function shareCategories() { const preferred = ['咖啡', '中餐', '泰餐', '肉食', '素食', '甜品', '酒吧', '活动', '自然', '住宿', '购物', '服务']; const found = data.items.flatMap(item => [item.detailCategory, item.category, ...(item.tags || [])]).filter(value => value && Array.from(String(value).trim()).length <= 4); return [...new Set([...preferred, ...found])].slice(0, 36); }
