function openPlaceEditor(id) { const item = data.items.find(x => x.id === id); if (!item || !(currentUser?.admin || currentUser?.coAdmin)) return; const photos = ownPhotos(item).map(x=>x.src).slice(0,3); $('#detailBody').innerHTML = `<p class="detail-tag">COMMUNITY EDITOR</p><h2 class="detail-title">${esc(t('editPlace'))}</h2><p class="share-lead">${esc(t('editLead'))}</p><form id="placeEditForm" class="share-form editor-form"><label><b>${esc(t('displayName'))} *</b><input id="editDisplayName" maxlength="100" required value="${esc(item.displayName || item.name || item.title)}"></label><label><b>${esc(t('memoryLabel'))}</b><input id="editMemory" maxlength="12" value="${esc(item.memoryKeyword || '')}"></label><label><b>${esc(t('category'))} *</b><input id="editCategory" maxlength="8" required value="${esc(item.detailCategory || item.category || '')}"></label><label><b>${esc(t('tagsLabel'))}</b><small>用逗号分隔，最多 6 个</small><input id="editTags" value="${esc((item.tags || []).join('，'))}"></label><label><b>${esc(t('details'))}</b><textarea id="editDescription" maxlength="1200" rows="6">${esc(item.description || item.hint || '')}</textarea></label><label><b>${esc(t('phoneLabel'))}</b><input id="editPhone" inputmode="tel" value="${esc(item.contact?.phone || '')}"></label><label><b>${esc(t('websiteLabel'))}</b><input id="editWebsite" type="url" value="${esc(item.contact?.website || '')}" placeholder="https://"></label><label><b>${esc(t('hoursLabel'))}</b><small>每行一天，例如：星期三：休息</small><textarea id="editHours" rows="7">${esc((item.contact?.openingHours || []).join('\n'))}</textarea></label><label><b>${esc(t('mapsAddress'))}</b><input id="editMaps" type="url" value="${esc(item.maps?.[0] || '')}"></label><label><b>${esc(t('photoUrls'))}</b><small>每行一张，最多 3 张 HTTPS 图片</small><textarea id="editPhotos" rows="4">${esc(photos.join('\n'))}</textarea></label><button id="savePlaceEdit" class="primary" type="submit">${esc(t('saveChanges'))}</button><p id="placeEditError" class="error"></p><p id="placeEditResult" class="share-result" hidden></p></form>`; $('#placeEditForm').onsubmit = event => savePlaceEdit(event,id); }
async function savePlaceEdit(event,id) { event.preventDefault(); const button=$('#savePlaceEdit'), error=$('#placeEditError'); error.textContent=''; button.disabled=true; try { const body={ displayName:$('#editDisplayName').value.trim(), memoryKeyword:$('#editMemory').value.trim(), category:$('#editCategory').value.trim(), tags:$('#editTags').value.split(/[,，]/).map(x=>x.trim()).filter(Boolean), description:$('#editDescription').value.trim(), phone:$('#editPhone').value.trim(), website:$('#editWebsite').value.trim(), openingHours:$('#editHours').value.split('\n').map(x=>x.trim()).filter(Boolean), mapsUrl:$('#editMaps').value.trim(), photos:$('#editPhotos').value.split('\n').map(x=>x.trim()).filter(Boolean) }; await api(`/api/places/${encodeURIComponent(id)}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify(body)}); data=await api('/api/places'); renderCategories(); render(); $('#placeEditResult').hidden=false; $('#placeEditResult').textContent=t('savedChanges'); setTimeout(()=>openCard(id),700); } catch(err){ error.textContent=err.message; button.disabled=false; } }
document.addEventListener('click', event => { const editor = event.target.closest('[data-edit-place]'); if (editor) { openPlaceEditor(editor.dataset.editPlace); return; } const opener = event.target.closest('[data-open-place]'); if (opener) openCard(opener.dataset.openPlace); const legend = event.target.closest('[data-legend-cat]'); if (legend) { active = active === legend.dataset.legendCat ? '全部' : legend.dataset.legendCat; renderCategories(); render(); focusLocations(filteredItems()); } });
document.addEventListener('keydown', event => { const opener = event.target.closest?.('[data-open-place]'); if (opener && (event.key === 'Enter' || event.key === ' ')) { event.preventDefault(); openCard(opener.dataset.openPlace); } });
$('#closeDetail').onclick = () => $('#detail').close(); $('#detail').onclick = event => { if (event.target === $('#detail')) $('#detail').close(); };

function eventLabel(event) { const labels = { zh: { login_success:'登录成功',login_failed:'登录失败',login_disabled:'停用账户尝试登录',register_success:'注册成功',register_failed:'注册失败',logout:'退出登录',user_status_changed:'用户状态调整',user_admin_changed:'管理员权限调整',registration_code_created:'创建授权码',registration_code_imported:'增补历史授权码',registration_code_revoked:'停用授权码',login_rate_limited:'登录限流' }, en: { login_success:'Login successful',login_failed:'Login failed',login_disabled:'Disabled login attempt',register_success:'Registration successful',register_failed:'Registration failed',logout:'Logged out',user_status_changed:'User status changed',user_admin_changed:'Administrator role changed',registration_code_created:'Access code created',registration_code_imported:'Historical access code restored',registration_code_revoked:'Access code revoked',login_rate_limited:'Login rate limited' }, th: { login_success:'เข้าสู่ระบบสำเร็จ',login_failed:'เข้าสู่ระบบไม่สำเร็จ',login_disabled:'บัญชีที่ปิดพยายามเข้าสู่ระบบ',register_success:'สมัครสำเร็จ',register_failed:'สมัครไม่สำเร็จ',logout:'ออกจากระบบ',user_status_changed:'เปลี่ยนสถานะผู้ใช้',user_admin_changed:'เปลี่ยนสิทธิ์ผู้ดูแล',registration_code_created:'สร้างรหัสเชิญ',registration_code_imported:'เพิ่มรหัสเชิญเดิม',registration_code_revoked:'ยกเลิกรหัสเชิญ',login_rate_limited:'จำกัดการเข้าสู่ระบบ' } }; return labels[language]?.[event] || event; }
async function copyText(value, button) { try { await navigator.clipboard.writeText(value); } catch { const area = document.createElement('textarea'); area.value = value; area.style.position = 'fixed'; area.style.opacity = '0'; document.body.append(area); area.select(); document.execCommand('copy'); area.remove(); } if (button) { const before = button.textContent; button.textContent = t('copied'); setTimeout(() => { if (button.isConnected) button.textContent = before; }, 1400); } }
function inviteText(code) { const vars = { url: 'https://cm.caishen.today', code }; return `${t('inviteZh', vars)}\n\n${t('inviteEn', vars)}`; }
async function openAdmin() { $('#userMenu').hidden = true; $('#adminDialog').showModal(); $('#adminBody').innerHTML = '<p class="loading">…</p>'; try { const overview = await api('/api/admin/overview'); renderAdmin(overview); } catch (error) { $('#adminBody').innerHTML = `<p class="error">${esc(error.message)}</p>`; } }
function renderAdmin(overview) { const statusName = { active: t('allow'), restricted: t('restrict'), disabled: t('disabled') }, emptyCodes = language === 'zh' ? '还没有授权码' : language === 'th' ? 'ยังไม่มีรหัสเชิญ' : 'No access codes yet', emptyActivity = language === 'zh' ? '暂无记录' : language === 'th' ? 'ยังไม่มีกิจกรรม' : 'No activity yet'; $('#adminBody').innerHTML = `<p class="detail-tag">ADMIN CONSOLE</p><h2 class="detail-title">${esc(t('adminTitle'))}</h2><div id="adminNotice" class="admin-notice" hidden></div><section class="admin-section"><div class="section-heading"><div><h3>${esc(t('users'))}</h3><p>${overview.users.length} ${esc(t('accounts'))}</p></div></div><div class="user-table">${overview.users.map(user => `<div class="user-row"><div class="user-identity"><strong>${esc(user.name)}</strong><small>${esc(user.id)}${user.admin ? ` · ${esc(t('administrator'))}` : ''}</small><small>${esc(t('lastLogin'))} ${user.lastLoginAt ? new Date(user.lastLoginAt).toLocaleString(language === 'zh' ? 'zh-CN' : language) : esc(t('never'))}</small></div><div class="user-controls"><label><span>${esc(t('role'))}</span><select data-user-admin="${esc(user.id)}" ${user.id === currentUser.id ? 'disabled' : ''}><option value="false" ${!user.admin ? 'selected' : ''}>${esc(t('member'))}</option><option value="true" ${user.admin ? 'selected' : ''}>${esc(t('administrator'))}</option></select></label><label><span>${esc(t('allow'))}</span><select data-user-status="${esc(user.id)}" ${user.id === currentUser.id ? 'disabled' : ''}>${Object.entries(statusName).map(([value, label]) => `<option value="${value}" ${user.status === value ? 'selected' : ''}>${esc(label)}</option>`).join('')}</select></label></div></div>`).join('')}</div></section><section class="admin-section"><div class="section-heading"><div><h3>${esc(t('codes'))}</h3><p>${esc(t('codeAdminHint'))}</p></div></div><form id="codeForm" class="inline-form"><input id="codeLabel" maxlength="40" placeholder="${esc(t('labelPlaceholder'))}"><select id="codeStyle"><option value="zh">${esc(t('zhCode'))}</option><option value="en">${esc(t('enCode'))}</option></select><input id="codeUses" type="number" min="1" max="100" value="1" aria-label="${esc(t('uses'))}"><button class="primary" type="submit">${esc(t('generate'))}</button></form><div class="code-list">${overview.codes.slice().reverse().map(code => { const remaining = Math.max(0, code.maxUses - code.used); return `<article class="code-row"><div class="code-info"><strong>${esc(code.label)}</strong><code>${esc(code.code || t('legacyCode'))}</code><span>${esc(t('used'))} ${code.used} · ${esc(t('remaining'))} ${remaining} · ${esc(code.active ? t('available') : t('stopped'))}</span></div><div class="code-actions">${code.code ? `<button type="button" data-copy-code="${esc(code.code)}">${esc(t('copyInvite'))}</button>` : ''}${code.active && remaining ? `<button class="danger-button" type="button" data-revoke-code="${esc(code.id)}">${esc(t('revoke'))}</button>` : ''}</div></article>`; }).join('') || `<p class="muted">${esc(emptyCodes)}</p>`}</div></section><section class="admin-section"><div class="section-heading"><div><h3>${esc(t('activity'))}</h3><p>${esc(t('activityHint'))}</p></div></div><div class="audit-list">${overview.audit.map(row => `<div><span>${esc(eventLabel(row.event))}</span><strong>${esc(row.user || row.target || '—')}</strong><time>${new Date(row.at).toLocaleString(language === 'zh' ? 'zh-CN' : language)}</time></div>`).join('') || `<p class="muted">${esc(emptyActivity)}</p>`}</div></section>`;
  $('#codeForm').insertAdjacentHTML('afterend', `<div class="manual-code-box"><div><strong>${esc(t('manualCodeTitle'))}</strong><p>${esc(t('manualCodeHint'))}</p></div><form id="manualCodeForm" class="inline-form manual-code-form"><input id="manualCode" required minlength="4" maxlength="32" autocomplete="off" placeholder="${esc(t('manualCodePlaceholder'))}"><input id="manualCodeLabel" maxlength="40" placeholder="${esc(t('labelPlaceholder'))}"><input id="manualCodeUses" type="number" min="1" max="100" value="1" aria-label="${esc(t('uses'))}"><button type="submit">${esc(t('importCode'))}</button></form></div>`);
  const notice = message => { const node = $('#adminNotice'); node.hidden = false; node.textContent = message; setTimeout(() => { if (node.isConnected) node.hidden = true; }, 2400); };
  document.querySelectorAll('[data-user-status]').forEach(select => select.onchange = async () => { try { await api(`/api/admin/users/${encodeURIComponent(select.dataset.userStatus)}/status`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ status: select.value }) }); notice(t('statusUpdated')); } catch (error) { notice(error.message); await openAdmin(); } });
  document.querySelectorAll('[data-user-admin]').forEach(select => select.onchange = async () => { try { await api(`/api/admin/users/${encodeURIComponent(select.dataset.userAdmin)}/admin`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ admin: select.value === 'true' }) }); await openAdmin(); } catch (error) { notice(error.message); await openAdmin(); } });
  $('#codeForm').onsubmit = async event => { event.preventDefault(); try { await api('/api/admin/codes', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ label: $('#codeLabel').value, style: $('#codeStyle').value, maxUses: Number($('#codeUses').value) }) }); await openAdmin(); } catch (error) { notice(error.message); } };
  $('#manualCodeForm').onsubmit = async event => { event.preventDefault(); try { await api('/api/admin/codes/manual', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ code: $('#manualCode').value.trim(), label: $('#manualCodeLabel').value, maxUses: Number($('#manualCodeUses').value) }) }); await openAdmin(); } catch (error) { notice(error.message); } };
  document.querySelectorAll('[data-copy-code]').forEach(button => button.onclick = () => copyText(inviteText(button.dataset.copyCode), button));
  document.querySelectorAll('[data-revoke-code]').forEach(button => button.onclick = async () => { if (!confirm(t('confirmRevoke'))) return; try { await api(`/api/admin/codes/${encodeURIComponent(button.dataset.revokeCode)}`, { method: 'DELETE' }); await openAdmin(); } catch (error) { notice(error.message); } });
}
$('#adminButton').onclick = openAdmin; $('#closeAdmin').onclick = () => $('#adminDialog').close(); $('#adminDialog').onclick = event => { if (event.target === $('#adminDialog')) $('#adminDialog').close(); };

document.addEventListener('error', event => { const image = event.target; if (!(image instanceof HTMLImageElement) || !image.matches('[data-place-image]') || image.dataset.failed) return; image.dataset.failed = 'true'; const figure = image.closest('figure'); if (figure) { figure.classList.add('image-failed'); image.remove(); if (!figure.querySelector('.image-fallback')) figure.insertAdjacentHTML('afterbegin', `<div class="image-fallback" role="img" aria-label="${esc(t('imageUnavailable'))}"><span>□</span><small>${esc(t('imageUnavailable'))}</small></div>`); } else image.remove(); }, true);

if ('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js');
applyLanguage();
boot();
